export type ModelProvider = 'ollama' | 'deepseek' | 'qwen' | 'gpt' | 'kimi';
export type FileAttachment = { id:string; name:string; size:number; mime:string; contextReady:boolean; createdAt:string };
export type MessageBase = { id:string; role:'user'|'assistant'; status:'complete'|'pending'|'error'; createdAt:string; source:'user'|'model'|'demo'|'tool'; attachments:FileAttachment[]; requestId?:string; errorCode?:string };
export type TextMessage = MessageBase & { type:'text'; content:{ markdown:string } };
export type TableMessage = MessageBase & {type:'table';content:{title:string;columns:string[];rows:(string|number|null)[][]}};
export type ChartMessage = MessageBase & {type:'chart';content:{title:string;labels:string[];values:number[];unit:string}};
export type ReportMessage = MessageBase & {type:'report';content:{title:string;summary:string;markdown:string}};
export type WriteOperationType='create'|'update'|'delete'|'batch-delete';
export type WriteRiskLevel='low'|'medium'|'high';
export type WriteApprovalStatus='pending'|'approved'|'rejected'|'expired'|'executed'|'failed';
export type WritePreviewField={key:string;label:string;value?:unknown;before?:unknown;after?:unknown;changed?:boolean};
export type WritePreviewItem={id:string;label:string;fields:WritePreviewField[]};
export type WriteToolPreviewDetails={title:string;action:WriteOperationType;entityType:'user'|'company';riskLevel:WriteRiskLevel;summary:string;riskMessages:string[];fields:WritePreviewField[];items?:WritePreviewItem[]};
export type ConfirmationMessage = MessageBase & {type:'confirmation';content:{title:string;description:string;decision:'pending'|'approved'|'rejected';demoOnly:boolean;approvalId?:string;taskId?:string;tool?:string;approvalStatus?:WriteApprovalStatus;preview?:WriteToolPreviewDetails;result?:unknown;error?:string}};
export type ChatMessage = TextMessage | TableMessage | ChartMessage | ReportMessage | ConfirmationMessage | ToolMessage;
export type ChatSession = {id:string;title:string;provider:ModelProvider;model:string;state:'idle'|'thinking';isDemo:boolean;createdAt:string;updatedAt:string};
export type ChatSnapshot = {session:ChatSession;messages:ChatMessage[]};
export type ModelProfile = {provider:ModelProvider;label:string;model:string;configured:boolean;isLocal:boolean;isDefault:boolean};
export type SendMessageInput = {text:string;fileIds:string[];requestId:string};

export type ToolIntent='QUERY_DATA'|'STATISTICS_ANALYSIS'|'MUTATE_DATA';
export type ToolContext={userId:string;tenantId:string;ip:string;visibleUserIds?:readonly string[]};
export type ToolPage={page:number;limit:number;total:number;sortBy?:string;sortDirection?:'asc'|'desc'};
export type ToolUser={id:string;name:string;email:string;role:string;status:string};
export type ToolCompany={id:string;name:string;level:string;country:string;city:string|null;founded_year:number|null;annual_revenue:number|null;employees:number|null;efficiency:number|null;efficiencyStrength:number};
export type ToolUsersData={kind:'users';title:string;rows:ToolUser[];pagination:ToolPage;roles:string[]};
export type ToolCompaniesData={kind:'companies';title:string;rows:ToolCompany[];pagination:ToolPage;options:{level:string[];country:string[];city:string[]}};
export type ToolDashboardData={kind:'dashboard';title:string;summary:{companyCount:number;totalRevenue:string;countryCount:number;totalEmployees:string;revenueReported:number;employeesReported:number};levels:{level:string;count:number;percentage:number}[];growth:{year:number;added:number;cumulative:number}[];coverage:{yearKnown:number;yearExcluded:number;yearMissing:number;yearInvalid:number};generatedAt:string;asOfYear:number};
export type ToolBarData={kind:'bar';title:string;dimension:'level'|'country'|'city';total:number;groups:{value:string|null;count:number;percentage:number}[];pagination:ToolPage;options:{level:string[];country:string[];city:string[]};generatedAt:string};
export type ToolData=ToolUsersData|ToolCompaniesData|ToolDashboardData|ToolBarData|{kind:'text';text:string};
export type ToolResult={code:string;data:ToolData|null;message:string;resultType:'text'|'table'|'chart'|'report';tool:string;requestId:string;durationMs?:number;cacheHit?:boolean;parameters?:Record<string,unknown>};
export type ToolDescriptor={name:string;label:string;intent:ToolIntent;permission:string;operation:'read';resultType:ToolResult['resultType'];enabled:boolean;allowed:boolean};
export type ToolExecuteInput={name:string;parameters:Record<string,unknown>;sessionId?:string;requestId?:string};
export type ToolMessage=MessageBase&{type:'tool';content:{result:ToolResult}};
export type WriteToolDescriptor={name:string;label:string;intent:'MUTATE_DATA';permission:string;operation:'write';enabled:boolean;allowed:boolean;autoExecute:false;confirmationRequired:true};
export type WriteToolPreview={code:'PREVIEW_READY';tool:string;operation:'write';autoExecute:false;confirmationRequired:true;message:string;preview:WriteToolPreviewDetails;durationMs:number};
export type WriteApprovalRequest={code:'APPROVAL_REQUIRED';tool:string;operation:'write';message:string;approvalId:string;taskId:string;status:'pending';expiresAt:string;preview:WriteToolPreviewDetails};
export type WriteApprovalDecisionResult={code:'WRITE_EXECUTED'|'WRITE_REJECTED';message:string;approvalId:string;taskId:string;status:WriteApprovalStatus;result?:unknown};
export type WriteApprovalListItem={approvalId:string;taskId:string;sessionId:string|null;tool:string;operationType:WriteOperationType;riskLevel:WriteRiskLevel;approvalStatus:WriteApprovalStatus;taskStatus:string;progress:number;title:string;createdAt:string;updatedAt:string;expiresAt:string;decidedAt:string|null;executedAt:string|null};
export type WriteApprovalDetail=WriteApprovalListItem&{preview:WriteToolPreviewDetails;rejectionReason:string|null;result:unknown;rollbackSnapshots:Record<string,unknown>;executionLog:{time:string;status:string;message:string}[]};
